using System.Text;using System;using System.Collections.Generic;using System.IO;using System.IO.Compression;using System.Linq;using System.Threading;using System.Web.Script.Serialization;
namespace PCMonitor {
 public static class SelfTest {
  public static int Run(string root){Directory.CreateDirectory(root);var tests=new List<object>();int failed=0;
   Action<string,Action> test=(name,body)=>{try{body();tests.Add(new{name=name,passed=true});}catch(Exception ex){failed++;tests.Add(new{name=name,passed=false,error=ex.Message});}};
   test("redaction_tokens_and_profile",()=>{string profile=Environment.GetFolderPath(Environment.SpecialFolder.UserProfile);if(String.IsNullOrEmpty(profile))profile=@"C:\Users\test-user";string source=profile+@"\game authToken=secret123 password=abc RiotClientAuthToken=private Bearer abc.def.ghi";string clean=Util.Clean(source);Assert(!clean.Contains("secret123")&&!clean.Contains("password=abc")&&!clean.Contains("=private")&&!clean.Contains("abc.def.ghi"),"Secret not redacted");Assert(clean.Contains("%USERPROFILE%"),"Profile not redacted");});
   test("gpu_parser_numeric_and_na",()=>{var g=Nvidia.Parse("NVIDIA GeForce RTX 4060 Ti, 616.56, 45, 42, 3210, 16380, 51.7, 0");Assert(g.temperature_c==45&&g.vram_total_mb==16380&&g.power_w==51.7,"GPU numeric parsing");g=Nvidia.Parse("GPU, 1, N/A, [N/A], 0, 0, N/A, 0");Assert(g.temperature_c==null&&g.power_w==null&&g.utilization_percent==null,"Unavailable must be null");});
   test("configuration_clamps",()=>{var s=new Settings{sample_seconds=0,log_seconds=0,retention_days=999,max_log_mb=1};s.Validate();Assert(s.sample_seconds==2&&s.log_seconds==2&&s.retention_days==30&&s.max_log_mb==25,"Invalid settings accepted");s.Save(root);var r=Settings.Read(root);Assert(r.retention_days==30,"Settings round trip failed");});
   test("appearance_persistence_and_legacy_settings",()=>{string folder=Path.Combine(root,"appearance-test");Directory.CreateDirectory(folder);File.WriteAllText(Path.Combine(folder,"settings.json"),"{\"retention_days\":12}");var legacy=Settings.Read(folder);Assert(legacy.theme=="dark"&&legacy.retention_days==12,"Legacy settings changed");legacy.theme="light";legacy.Save(folder);var loaded=Settings.Read(folder);Assert(loaded.theme=="light"&&loaded.retention_days==12,"Light theme lost after restart");loaded.theme="dark";loaded.Save(folder);Assert(Settings.Read(folder).theme=="dark","Dark theme lost after restart");loaded.theme="unsupported";loaded.Validate();Assert(loaded.theme=="dark","Invalid theme accepted");});
   test("jsonl_nulls_export_and_retention",()=>{string folder=Path.Combine(root,"store-test");var s=new Settings{retention_days=2,max_log_mb=25};var store=new LogStore(folder,s);store.Write("metrics",new Snapshot{timestamp_utc=Util.Utc(),session_id=store.Session,cpu_percent=null});Assert(String.IsNullOrEmpty(store.LastError),store.LastError);var logs=Directory.GetFiles(Path.Combine(folder,"logs"),"*.jsonl");var parsed=new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(File.ReadLines(logs[0]).First());Assert(parsed.ContainsKey("cpu_percent")&&parsed["cpu_percent"]==null,"Null metrics changed to zero");string old=Path.Combine(folder,"logs","metrics-old.jsonl");File.WriteAllText(old,"{}\n");File.SetLastWriteTimeUtc(old,DateTime.UtcNow.AddDays(-10));store.Cleanup();Assert(!File.Exists(old),"Old logs not removed");string external=Path.Combine(folder,"keep.txt");File.WriteAllText(external,"keep");store.Cleanup();Assert(File.Exists(external),"Non-log data deleted");string zip=store.Export(Path.Combine(root,"exports"),new Snapshot());using(var a=ZipFile.OpenRead(zip)){Assert(a.GetEntry("manifest.json")!=null&&a.GetEntry("LEIA-ME-IA.txt")!=null&&a.Entries.Any(x=>x.FullName.StartsWith("logs/")),"Bundle incomplete");}});
   test("concurrent_append_and_export",()=>{var store=new LogStore(Path.Combine(root,"concurrent-test-"+Guid.NewGuid().ToString("N")),new Settings());System.Threading.Tasks.Parallel.For(0,80,n=>store.Write("incidents",new{index=n,type="test"}));var lines=Directory.GetFiles(Path.Combine(store.Root,"logs"),"*.jsonl").SelectMany(File.ReadAllLines).ToArray();Assert(lines.Length==80,"Concurrent records missing");var ids=lines.Select(line=>new JavaScriptSerializer().Deserialize<Dictionary<string,object>>(line)["index"]).Distinct().Count();Assert(ids==80,"Concurrent records duplicated or damaged");});
   test("disk_native_abi",()=>{Assert(System.Runtime.InteropServices.Marshal.OffsetOf(typeof(NativeDiskQuery.Formatted),"Value").ToInt32()==8,"Invalid PDH double alignment");Assert(System.Runtime.InteropServices.Marshal.OffsetOf(typeof(NativeDiskQuery.CounterInfo),"Object").ToInt32()==56,"Invalid PDH version/pointer layout");});
   test("disk_initial_failure_retries_and_recovers",()=>{DateTime now=DateTime.UtcNow;int calls=0;var fake=new FakeDiskQuery();using(var collector=new DiskCollector(()=>{calls++;if(calls==1)throw new InvalidOperationException("simulated unavailable");return fake;},()=>now)){Assert(collector.Read().Count==0&&collector.Status=="unavailable","Failure must be unavailable");Assert(collector.LastError.Contains("simulated"),"Detailed error missing");collector.Read();Assert(calls==1,"Retry backoff ignored");now=now.AddSeconds(31);Assert(collector.Read().Count==0&&collector.Status=="warming_up","Initial sample must warm up");Assert(collector.Read().Single().active_percent==42&&collector.Status=="ok","Recovery failed");}Assert(fake.Disposed,"Native query not disposed");});
   test("disk_read_failure_recreates_query",()=>{DateTime now=DateTime.UtcNow;int calls=0;var first=new FakeDiskQuery();using(var collector=new DiskCollector(()=>{calls++;return calls==1?first:new FakeDiskQuery();},()=>now)){collector.Read();collector.Read();first.fail=true;Assert(collector.Read().Count==0&&collector.Status=="unavailable"&&first.Disposed,"Failed query not closed");now=now.AddSeconds(31);collector.Read();Assert(collector.Read().Count==1&&calls==2,"No recovery after query failure");}});
   test("repository_handles_partial_lines_and_bounds",()=>{string folder=Path.Combine(root,"repository-test-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(folder,"logs"));string file=Path.Combine(folder,"logs","metrics-test.jsonl");File.WriteAllText(file,"{\"type\":\"metrics\",\"timestamp_utc\":\""+Util.Utc()+"\",\"cpu_percent\":42}\n{incomplete");var repo=new LogRepository(folder);Assert(repo.Rows("metrics",DateTime.UtcNow.AddMinutes(-1),10,null).Count==1,"Partial final line discarded valid data");Assert(Convert.ToInt32(repo.Latest()["cpu_percent"])==42,"Latest metric missing");bool rejected=false;try{repo.Rows("../secrets",DateTime.MinValue,1,null);}catch(ArgumentException){rejected=true;}Assert(rejected,"Unapproved log path accepted");});
   test("log_size_cap",()=>{var store=new LogStore(Path.Combine(root,"cap-test"),new Settings{max_log_mb=25});string f=Path.Combine(store.Root,"logs","large.jsonl");using(var fs=File.Create(f))fs.SetLength(26L*1024*1024);store.Cleanup();Assert(store.Size()<=25L*1024*1024,"Size cap not applied");});
   var result=new{success=failed==0,tests=tests,failed=failed};File.WriteAllText(Path.Combine(root,"selftest-result.json"),new JavaScriptSerializer().Serialize(result),new UTF8Encoding(false));return failed==0?0:1;
  }
  static void Assert(bool condition,string message){if(!condition)throw new Exception(message);}
 }
}
